          "starterCode": "public class MyList {\n    MyListNode head, tail;\n    int size;\n\n    MyList() {\n        head = tail = null;\n        size = 0;\n    }\n\n    boolean isEmpty() {\n        return head == null;\n    }\n\n    void clear() {\n        head = tail = null;\n        size = 0;\n    }\n\n    // Q1.1 [1 mark] addLast - if xBrand.charAt(0)=='B' then do nothing;\n    // otherwise add a new node with brand=xBrand, color=xColor, weight=xWeight\n    // to the end of the list.\n    void addLast(String xBrand, int xColor, int xWeight) {\n        //You should write here appropriate statements to complete this function.\n\n    }\n\n    void print() {\n        MyListNode p = head;\n        while (p != null) {\n            System.out.print(p.info + \" \");\n            p = p.next;\n        }\n        System.out.println();\n    }\n\n    // Do not edit — tests addLast() above.\n    void f1() {\n        clear();\n        addLast(\"A\", 9, 8);\n        addLast(\"B\", 1, 1);   // brand starts with 'B': must be skipped\n        addLast(\"C\", 6, 5);\n        addLast(\"D\", 2, 4);\n        addLast(\"E\", 7, 9);\n        addLast(\"F\", 4, -7);\n        addLast(\"G\", -3, 2);\n        print(); // -> f1.txt\n    }\n\n    // Q1.2 [1 mark] f2 - insert x, y so x becomes the 2nd node and y becomes\n    // the 5th node.\n    void f2() {\n        clear();\n        addLast(\"C\", 9, 8);\n        addLast(\"D\", 6, 3);\n        addLast(\"E\", 8, 5);\n        addLast(\"F\", 5, 4);\n        addLast(\"I\", 4, 9);\n        addLast(\"J\", 3, 7);\n        print(); // before\n\n        Bike x = new Bike(\"X\", 1, 2);\n        Bike y = new Bike(\"Y\", 3, 4);\n\n        //You should write here appropriate statements to complete this function.\n\n\n        print(); // after -> f2.txt\n    }\n\n    // Q1.3 [1 mark] f3 - remove the SECOND node having the minimum color\n    // (if there is only one node with the minimum color, do nothing).\n    void f3() {\n        clear();\n        addLast(\"C\", 8, 6);\n        addLast(\"D\", 3, 8);\n        addLast(\"E\", 9, 2);\n        addLast(\"F\", 5, -1);\n        addLast(\"G\", 3, 7);\n        addLast(\"H\", 6, 8);\n        addLast(\"I\", 7, 3);\n        print(); // before\n\n        //You should write here appropriate statements to complete this function.\n\n\n        print(); // after -> f3.txt\n    }\n\n    // Q1.4 [1 mark] f4 - the list has at least 7 elements. Sort the first 4\n    // elements ascending by color, and the last 3 elements descending by\n    // color.\n    void f4() {\n        clear();\n        addLast(\"C\", 9, 8);\n        addLast(\"D\", 3, 2);\n        addLast(\"E\", 10, 7);\n        addLast(\"F\", 1, 9);\n        addLast(\"I\", 6, 4);\n        addLast(\"J\", 11, 5);\n        addLast(\"K\", 7, 6);\n        print(); // before\n\n        //You should write here appropriate statements to complete this function.\n\n\n        print(); // after -> f4.txt\n    }\n\n    public static void main(String[] args) {\n        MyList t = new MyList();\n        System.out.println(\"=== f1 ===\");\n        t.f1();\n        System.out.println(\"=== f2 ===\");\n        t.f2();\n        System.out.println(\"=== f3 ===\");\n        t.f3();\n        System.out.println(\"=== f4 ===\");\n        t.f4();\n    }\n}\n",
          "sampleSolution": "public class MyList {\n    MyListNode head, tail;\n    int size;\n\n    MyList() {\n        head = tail = null;\n        size = 0;\n    }\n\n    boolean isEmpty() {\n        return head == null;\n    }\n\n    void clear() {\n        head = tail = null;\n        size = 0;\n    }\n\n    // Q1.1 [1 mark] addLast - if xBrand.charAt(0)=='B' then do nothing;\n    // otherwise add a new node with brand=xBrand, color=xColor, weight=xWeight\n    // to the end of the list.\n    void addLast(String xBrand, int xColor, int xWeight) {\n        if (xBrand.charAt(0) == 'B') return;\n        MyListNode p = new MyListNode(new Bike(xBrand, xColor, xWeight));\n        if (isEmpty()) {\n            head = tail = p;\n        } else {\n            tail.next = p;\n            tail = p;\n        }\n        size++;\n    }\n\n    void print() {\n        MyListNode p = head;\n        while (p != null) {\n            System.out.print(p.info + \" \");\n            p = p.next;\n        }\n        System.out.println();\n    }\n\n    // Do not edit — tests addLast() above.\n    void f1() {\n        clear();\n        addLast(\"A\", 9, 8);\n        addLast(\"B\", 1, 1);   // brand starts with 'B': must be skipped\n        addLast(\"C\", 6, 5);\n        addLast(\"D\", 2, 4);\n        addLast(\"E\", 7, 9);\n        addLast(\"F\", 4, -7);\n        addLast(\"G\", -3, 2);\n        print(); // -> f1.txt\n    }\n\n    // Q1.2 [1 mark] f2 - insert x, y so x becomes the 2nd node and y becomes\n    // the 5th node.\n    void f2() {\n        clear();\n        addLast(\"C\", 9, 8);\n        addLast(\"D\", 6, 3);\n        addLast(\"E\", 8, 5);\n        addLast(\"F\", 5, 4);\n        addLast(\"I\", 4, 9);\n        addLast(\"J\", 3, 7);\n        print(); // before\n\n        Bike x = new Bike(\"X\", 1, 2);\n        Bike y = new Bike(\"Y\", 3, 4);\n\n        MyListNode px = new MyListNode(x);\n        px.next = head.next;\n        head.next = px;\n        size++;\n\n        MyListNode p3 = nodeAt(3); // after inserting x, the 4th node (index 3)\n        Bike tmpY = y;\n        MyListNode py = new MyListNode(tmpY);\n        py.next = p3.next;\n        p3.next = py;\n        size++;\n\n        print(); // after -> f2.txt\n    }\n\n    // Q1.3 [1 mark] f3 - remove the SECOND node having the minimum color\n    // (if there is only one node with the minimum color, do nothing).\n    void f3() {\n        clear();\n        addLast(\"C\", 8, 6);\n        addLast(\"D\", 3, 8);\n        addLast(\"E\", 9, 2);\n        addLast(\"F\", 5, -1);\n        addLast(\"G\", 3, 7);\n        addLast(\"H\", 6, 8);\n        addLast(\"I\", 7, 3);\n        print(); // before\n\n        int min = Integer.MAX_VALUE;\n        for (MyListNode p = head; p != null; p = p.next) min = Math.min(min, p.info.color);\n        int count = 0;\n        MyListNode prev = null, cur = head;\n        while (cur != null) {\n            if (cur.info.color == min) {\n                count++;\n                if (count == 2) {\n                    prev.next = cur.next;\n                    if (cur == tail) tail = prev;\n                    size--;\n                    break;\n                }\n            }\n            prev = cur;\n            cur = cur.next;\n        }\n\n        print(); // after -> f3.txt\n    }\n\n    // Q1.4 [1 mark] f4 - the list has at least 7 elements. Sort the first 4\n    // elements ascending by color, and the last 3 elements descending by\n    // color.\n    void f4() {\n        clear();\n        addLast(\"C\", 9, 8);\n        addLast(\"D\", 3, 2);\n        addLast(\"E\", 10, 7);\n        addLast(\"F\", 1, 9);\n        addLast(\"I\", 6, 4);\n        addLast(\"J\", 11, 5);\n        addLast(\"K\", 7, 6);\n        print(); // before\n\n        sortRange(0, 3, true);\n        sortRange(size - 3, size - 1, false);\n\n        print(); // after -> f4.txt\n    }\n\n    private void sortRange(int lo, int hi, boolean ascending) {\n        for (int i = lo; i < hi; i++) {\n            for (int j = lo; j < hi - (i - lo); j++) {\n                MyListNode a = nodeAt(j), b = nodeAt(j + 1);\n                boolean shouldSwap = ascending ? a.info.color > b.info.color : a.info.color < b.info.color;\n                if (shouldSwap) {\n                    Bike tmp = a.info; a.info = b.info; b.info = tmp;\n                }\n            }\n        }\n    }\n\n    private MyListNode nodeAt(int pos) {\n        MyListNode p = head;\n        for (int i = 0; i < pos; i++) p = p.next;\n        return p;\n    }\n\n    public static void main(String[] args) {\n        MyList t = new MyList();\n        System.out.println(\"=== f1 ===\");\n        t.f1();\n        System.out.println(\"=== f2 ===\");\n        t.f2();\n        System.out.println(\"=== f3 ===\");\n        t.f3();\n        System.out.println(\"=== f4 ===\");\n        t.f4();\n    }\n}\n",
