          "sampleSolution": "import java.util.LinkedList;\nimport java.util.Queue;\n\npublic class BSTree {\n    BSTNode root;\n\n    BSTree() {\n        root = null;\n    }\n\n    void clear() {\n        root = null;\n    }\n\n    // Q2.1 [1 mark] insert - if xBrand.charAt(0)=='A' then do nothing;\n    // otherwise insert new Bike with brand=xBrand, color=xColor,\n    // weight=xWeight into the tree (weight is the unique key).\n    void insert(String xBrand, int xColor, int xWeight) {\n        if (xBrand.charAt(0) == 'A') return;\n        BSTNode p = new BSTNode(new Bike(xBrand, xColor, xWeight));\n        if (root == null) { root = p; return; }\n        BSTNode cur = root, parent = null;\n        while (cur != null) {\n            if (cur.info.weight == xWeight) return; // unique key, reject duplicate\n            parent = cur;\n            if (xWeight < cur.info.weight) cur = cur.left;\n            else cur = cur.right;\n        }\n        if (xWeight < parent.info.weight) parent.left = p;\n        else parent.right = p;\n    }\n\n    private void loadBase() {\n        clear();\n        insert(\"B\", 9, 4);\n        insert(\"A\", 5, 1);   // brand starts with 'A': must be skipped\n        insert(\"C\", 4, 3);\n        insert(\"D\", 8, 6);\n        insert(\"E\", 2, 5);\n        insert(\"F\", -6, 7);\n        insert(\"G\", 6, 8);\n        insert(\"H\", 10, 2);\n        insert(\"I\", 1, 9);\n    }\n\n    void breadth(BSTNode p) {\n        if (p == null) return;\n        Queue<BSTNode> q = new LinkedList<>();\n        q.add(p);\n        while (!q.isEmpty()) {\n            BSTNode r = q.poll();\n            System.out.print(r.info + \" \");\n            if (r.left != null) q.add(r.left);\n            if (r.right != null) q.add(r.right);\n        }\n        System.out.println();\n    }\n\n    void inOrder(BSTNode p) {\n        if (p == null) return;\n        inOrder(p.left);\n        System.out.print(p.info + \" \");\n        inOrder(p.right);\n    }\n\n    void inOrderRoot() {\n        inOrder(root);\n        System.out.println();\n    }\n\n    void postOrder(BSTNode p) {\n        if (p == null) return;\n        postOrder(p.left);\n        postOrder(p.right);\n        System.out.print(p.info + \" \");\n    }\n\n    // Do not edit — tests insert() above.\n    void f1() {\n        loadBase();\n        breadth(root);\n        inOrderRoot();\n    }\n\n    // Q2.2 [1 mark] f2 - perform the post-order traversal from the root but\n    // write only the nodes with color<7. (Hint: copy postOrder(...) to\n    // postOrder2(...) and modify it.)\n    void f2() {\n        loadBase();\n        postOrder2(root);\n        System.out.println();\n    }\n\n    private void postOrder2(BSTNode p) {\n        if (p == null) return;\n        postOrder2(p.left);\n        postOrder2(p.right);\n        if (p.info.color < 7) System.out.print(p.info + \" \");\n    }\n\n    // Q2.3 [1 mark] f3 - perform breadth-first traversal from the root and\n    // find the SECOND node p having 2 children. If such a node does not\n    // exist, do nothing; otherwise delete the node q = p.right by copying.\n    void f3() {\n        loadBase();\n        breadth(root); // before\n\n        BSTNode second = findSecondTwoChildNode();\n        if (second != null) {\n            second.right = deleteByCopy(second.right);\n        }\n\n        breadth(root); // after -> f3.txt\n    }\n\n    private BSTNode findSecondTwoChildNode() {\n        int count = 0;\n        Queue<BSTNode> q = new LinkedList<>();\n        if (root != null) q.add(root);\n        while (!q.isEmpty()) {\n            BSTNode r = q.poll();\n            if (r.left != null && r.right != null) {\n                count++;\n                if (count == 2) return r;\n            }\n            if (r.left != null) q.add(r.left);\n            if (r.right != null) q.add(r.right);\n        }\n        return null;\n    }\n\n    // Standard delete-by-copy: 0/1 child -> promote the child; 2 children ->\n    // copy in-order successor's data, then delete the successor.\n    private BSTNode deleteByCopy(BSTNode p) {\n        if (p == null) return null;\n        if (p.left == null || p.right == null) {\n            return (p.left != null) ? p.left : p.right;\n        }\n        BSTNode succ = p.right;\n        while (succ.left != null) succ = succ.left;\n        p.info = succ.info;\n        p.right = deleteByCopyByWeight(p.right, succ.info.weight);\n        return p;\n    }\n\n    private BSTNode deleteByCopyByWeight(BSTNode p, int weight) {\n        if (p == null) return null;\n        if (p.info.weight == weight) return deleteByCopy(p);\n        if (weight < p.info.weight) p.left = deleteByCopyByWeight(p.left, weight);\n        else p.right = deleteByCopyByWeight(p.right, weight);\n        return p;\n    }\n\n    // Q2.4 [1 mark] f4 - find the node p having maximum weight. Suppose f is\n    // the father of p. Check if f is not null then rotate f about p.\n    void f4() {\n        loadBase();\n        breadth(root); // before\n\n        BSTNode maxNode = root, parent = null;\n        BSTNode cur = root, curParent = null;\n        while (cur != null) {\n            if (cur.info.weight > maxNode.info.weight) { maxNode = cur; parent = curParent; }\n            curParent = cur;\n            cur = cur.right; // max weight is always found by following .right\n        }\n        if (parent != null) {\n            rotateAbout(parent, maxNode);\n        }\n\n        breadth(root); // after -> f4.txt\n    }\n\n    // Rotate father `f` about child `p` (p is one of f's children): p takes\n    // f's place in the tree, f becomes p's child on the opposite side, and\n    // p's former child on that opposite side becomes f's child instead.\n    private void rotateAbout(BSTNode f, BSTNode p) {\n        BSTNode grandparent = findParent(root, f);\n        boolean pIsRightChild = (f.right == p);\n\n        if (pIsRightChild) {\n            f.right = p.left;\n            p.left = f;\n        } else {\n            f.left = p.right;\n            p.right = f;\n        }\n\n        if (grandparent == null) {\n            root = p;\n        } else if (grandparent.left == f) {\n            grandparent.left = p;\n        } else {\n            grandparent.right = p;\n        }\n    }\n\n    private BSTNode findParent(BSTNode root, BSTNode child) {\n        if (root == null || root == child) return null;\n        if (root.left == child || root.right == child) return root;\n        BSTNode p = findParent(root.left, child);\n        return (p != null) ? p : findParent(root.right, child);\n    }\n\n    public static void main(String[] args) {\n        BSTree t = new BSTree();\n        System.out.println(\"=== f1 ===\");\n        t.f1();\n        System.out.println(\"=== f2 ===\");\n        t.f2();\n        System.out.println(\"=== f3 ===\");\n        t.f3();\n        System.out.println(\"=== f4 ===\");\n        t.f4();\n    }\n}\n",
